var productMessageRegistry = func() *localize.Registry {
	registry := localize.NewRegistry()
	for locale, messages := range productMessages {
		if err := registry.Register(localize.Catalog{Locale: locale, Version: productCatalogVersion, Messages: productCatalogMessages(locale, messages)}); err != nil {
			panic(err)
		}
	}
	return registry
}()

// productCatalogMessages keeps protocol and storage vocabulary out of
// ordinary availability cards while leaving the admin/status/provenance
// messages that explain authorized diagnostics untouched. The source map is
// cloned so the reviewed catalog remains available to coverage tooling.
func productCatalogMessages(locale string, source map[string]localize.Message) map[string]localize.Message {
	messages := make(map[string]localize.Message, len(source))
	for key, message := range source {
		messages[key] = message
	}
	for key, message := range messages {
		if strings.HasSuffix(key, ".unavailable_detail") && key != "myself.unavailable_detail" {
			message.Text = ordinaryUnavailableCopy(locale)
			message.Plural = nil
			message.Gender = nil
			messages[key] = message
		}
		if strings.HasSuffix(key, ".return_home") {
			message.Text = ordinaryReturnHomeCopy(locale)
			message.Plural = nil
			message.Gender = nil
			messages[key] = message
		}
	}
	// Availability details are task-oriented copy in every supported locale,
	// including keys that have not yet received a full translation. Registering
	// this small shared set prevents an English technical fallback in an Arabic
	// or German unavailable state while leaving the rest of the rollout
	// observable through ProductCatalogCoverage.
	for key := range productMessages[DefaultProductLocale] {
		if _, ok := messages[key]; !ok {
			switch {
			case strings.HasSuffix(key, ".unavailable_detail") && key != "myself.unavailable_detail":
				messages[key] = localize.Message{Text: ordinaryUnavailableCopy(locale)}
			case strings.HasSuffix(key, ".return_home"):
				messages[key] = localize.Message{Text: ordinaryReturnHomeCopy(locale)}
			}
		}
	}
	for key, baseline := range productMessages[DefaultProductLocale] {
		if strings.HasPrefix(key, "page.") && strings.HasSuffix(key, ".subtitle") && strings.Contains(strings.ToLower(baseline.Text), "governed") {
			messages[key] = localize.Message{Text: ordinaryUnavailableCopy(locale)}
		}
	}
	for key := range map[string]struct{}{
		"organization.metadata_boundary": {}, "organization.empty_description": {},
		"page.home.subtitle": {}, "page.insights.subtitle": {}, "page.organization.subtitle": {},
		"page.journeys.subtitle": {}, "page.person.subtitle": {}, "action_launcher.promote_worker_description": {},
		"page.org_explorer.label": {}, "page.org_explorer.title": {}, "page.org_explorer.subtitle": {},
		"page.org_outline.label": {}, "page.org_outline.title": {}, "page.org_outline.subtitle": {},
		"page.org_responsive.label": {}, "page.org_responsive.title": {}, "page.org_responsive.subtitle": {},
		"page.admin.subtitle": {}, "page.appearance.subtitle": {}, "page.studio.subtitle": {},
		"page.roles.label": {}, "page.roles.title": {}, "page.roles.subtitle": {},
		"admin.journeys_unavailable_reason": {}, "admin.studio_unavailable_reason": {}, "admin.custom_description": {},
		"shell.load_recovery": {}, "shell.load_retry": {}, "shell.page_unavailable": {}, "shell.page_recovery": {}, "shell.live_source": {}, "shell.myself_unidentified": {},
		"work.server_proposal": {}, "person.employment_detail": {},
		"workflow.choose": {}, "appearance.brand_help": {},
		"studio.back_admin": {}, "studio.unavailable_badge": {}, "studio.unavailable_title": {}, "studio.unavailable_description": {}, "studio.return_home": {},
		"page.governed_feedback.label": {}, "page.governed_feedback.title": {}, "governed_feedback.unavailable_title": {},
		"page.skills_profile.title": {}, "page.governed_population.label": {}, "page.governed_population.title": {}, "governed_population.unavailable_title": {},
		"page.report_export.title": {}, "report_export.unavailable_title": {},
	} {
		if text := ordinaryCopy(locale, key); text != "" {
			messages[key] = localize.Message{Text: text}
		}
	}
	for key, translated := range peoplePersonTranslations(locale) {
		messages[key] = localize.Message{Text: translated}
	}
	switch locale {
	case "de-DE":
		messages["person.unreported_fields"] = localize.Message{Plural: map[string]string{"one": "{count} Feld nicht gemeldet", "other": "{count} Felder nicht gemeldet"}}
		messages["workflow.available_count"] = localize.Message{Plural: map[string]string{"one": "{count} verfügbar", "other": "{count} verfügbar"}}
		messages["history.count"] = localize.Message{Plural: map[string]string{"one": "{count} Eintrag", "other": "{count} Einträge"}}
	case "ar":
		messages["person.unreported_fields"] = localize.Message{Plural: map[string]string{"zero": "لا توجد حقول غير مذكورة", "one": "حقل واحد غير مذكور", "two": "حقلان غير مذكوران", "few": "{count} حقول غير مذكورة", "many": "{count} حقلًا غير مذكور", "other": "{count} حقل غير مذكور"}}
		messages["people.count"] = localize.Message{Plural: map[string]string{"zero": "لا يوجد أشخاص", "one": "شخص واحد", "two": "شخصان", "few": "{count} أشخاص", "many": "{count} شخصًا", "other": "{count} شخص"}}
		messages["workflow.available_count"] = localize.Message{Plural: map[string]string{"zero": "لا توجد مهام متاحة", "one": "مهمة واحدة متاحة", "two": "مهمتان متاحتان", "few": "{count} مهام متاحة", "many": "{count} مهمة متاحة", "other": "{count} مهمة متاحة"}}
		messages["history.count"] = localize.Message{Plural: map[string]string{"zero": "لا توجد سجلات", "one": "سجل واحد", "two": "سجلان", "few": "{count} سجلات", "many": "{count} سجلًا", "other": "{count} سجل"}}
	}
	return messages
}

