func ordinaryUnavailableCopy(locale string) string {
	switch locale {
	case "de-DE":
		return "Dieser Bereich ist noch nicht verfügbar. Kehren Sie zum Arbeitsbereich zurück, um eine andere Aufgabe fortzusetzen."
	case "ar":
		return "هذه المساحة غير متاحة بعد. عُد إلى مساحة العمل لمتابعة مهمة أخرى."
	default:
		return "This area is not available yet. Return to the workspace to continue with another task."
	}
}

func ordinaryReturnHomeCopy(locale string) string {
	switch locale {
	case "de-DE":
		return "Zurück zur Startseite"
	case "ar":
		return "العودة إلى الرئيسية"
	default:
		return "Back to Home"
	}
}
